import {player,deal,ask,tick} from './game.mjs'
import html from './page.html'
function check(b,msg){if(!b)throw Error(msg)}
function settings(r,b){check(Number.isSafeInteger(b.rounds)&&b.rounds>=1&&Number.isSafeInteger(b.seconds)&&b.seconds>=0,'Configuração inválida.');r.rounds=b.rounds;r.seconds=b.seconds}
export default {async fetch(req,env){if(new URL(req.url).pathname!='/api')return new Response(html,{headers:{'content-type':'text/html;charset=utf-8'}})
try{let b=await req.json(),key=req.headers.get('Authorization');check(/^[a-f0-9-]{36}$/i.test(key||''),'Sessão inválida.')
let code=String(b.code||'').toUpperCase(),db=env.DB,s=await db.prepare('SELECT * FROM rooms WHERE code=?').bind(code).first(),r=s&&JSON.parse(s.state),changed=false
if(b.action==='create'){code=crypto.randomUUID().slice(0,6).toUpperCase();let p=player(String(b.name||'Você').slice(0,24));r={code,players:[p],keys:{[key]:p.id},phase:'sala',round:0,rev:0};settings(r,b);await db.prepare('INSERT INTO rooms VALUES(?,0,?,?)').bind(code,JSON.stringify(r),Date.now()+86400000).run()}
else{check(r,'Sala não encontrada.');let me=r.players.find(p=>p.id===r.keys[key])
if(b.action==='join'&&!me){check(r.players.length<4&&r.phase==='sala','Sala cheia ou em jogo.');me=player(String(b.name||'Visitante').slice(0,24));r.keys[key]=me.id;r.players.push(me);changed=true}
check(me,'Entre na sala.');let host=me===r.players[0], timed=tick(r);changed ||= timed
if(!['join','poll'].includes(b.action)){check(b.rev===r.rev,'A mesa mudou. Tente novamente.')
if(b.action==='ask'){if(!timed){check(r.phase==='jogo'&&r.players[r.turn]===me,'Aguarde sua vez.');ask(r,b.target,b.n,b.color)}}
else{check(host,'Somente o anfitrião.');if(b.action==='bot'){check(r.phase==='sala'&&r.players.length<4,'Mesa cheia.');r.players.push(player('Computador '+r.players.length,true))}
else if(b.action==='start'){check(r.phase==='sala'&&r.players.length>=2,'Convide alguém ou adicione um computador.');settings(r,b);deal(r)}
else if(b.action==='next'){check(r.phase==='intervalo','Rodada em andamento.');deal(r)}
else if(b.action==='reset'){delete r.finalists;delete r.champion;r.round=0;r.phase='sala';for(let p of r.players)Object.assign(p,{hand:[],pairs:[],score:0,total:0})}
else if(b.action==='end'){r.phase='fim';r.result='Partida encerrada pelo anfitrião.'}else throw Error('Ação inválida.')}changed=true}
if(changed){r.rev++;let res=await db.prepare('UPDATE rooms SET state=?,version=? WHERE code=? AND version=?').bind(JSON.stringify(r),r.rev,code,s.version).run();check(res.meta.changes,'A mesa mudou. Tente novamente.')}}
let me=r.keys[key];return Response.json({...r,keys:undefined,deck:r.deck?.length,me,players:r.players.map(p=>({...p,count:p.hand.length,hand:p.id===me?p.hand:undefined}))})}catch(e){return Response.json({error:e.message},{status:400})}}}

